import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # Helper to check if a bracket sequence is valid
    def is_valid(seq):
        balance = 0
        for ch in seq:
            if ch == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # If already valid, no operation needed
    if is_valid(s):
        print("possible")
        return

    # Try all possible segments [l, r] (0-based)
    # Inversion: '(' becomes ')', ')' becomes '('
    # We can simulate this by reversing the effect or just flipping chars
    for l in range(n):
        for r in range(l, n):
            # Construct new sequence with inversion from l to r
            # To avoid string slicing overhead, we can build a list
            chars = list(s)
            for i in range(l, r + 1):
                if chars[i] == '(':
                    chars[i] = ')'
                else:
                    chars[i] = '('

            if is_valid("".join(chars)):
                print("possible")
                return

    print("impossible")

if __name__ == "__main__":
    solve()

